'use client';

import { Loader2 } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

const FIRST_INTERVAL_MS = 2000;
const MAX_INTERVAL_MS = 8000;
const MAX_MS = 60_000;

/**
 * Shown while a paid order's tickets/invoice are still being generated by the worker. Polls a
 * light status endpoint (counts only, backoff 2 s → 8 s) and reloads the page data once, when the
 * number of tickets or invoices changed.
 */
export function OrderAutoRefresh({
  orderId,
  token,
  initial,
}: {
  orderId: string;
  token: string | null;
  initial: { validTickets: number; invoices: number };
}) {
  const t = useTranslations('checkout.order.preparing');
  const router = useRouter();
  const [timedOut, setTimedOut] = useState(false);

  useEffect(() => {
    const started = Date.now();
    let timer: ReturnType<typeof setTimeout> | undefined;
    let cancelled = false;
    let delay = FIRST_INTERVAL_MS;
    const url = `/api/orders/${orderId}/status${token ? `?t=${encodeURIComponent(token)}` : ''}`;
    const poll = async () => {
      if (cancelled) return;
      if (Date.now() - started >= MAX_MS) {
        setTimedOut(true);
        return;
      }
      try {
        const response = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
        if (response.ok) {
          const status = (await response.json()) as { validTickets: number; invoices: number };
          if (
            status.validTickets !== initial.validTickets ||
            status.invoices !== initial.invoices
          ) {
            router.refresh();
            return;
          }
        }
      } catch {
        /* next poll retries */
      }
      delay = Math.min(MAX_INTERVAL_MS, Math.round(delay * 1.4));
      timer = setTimeout(() => void poll(), delay);
    };
    timer = setTimeout(() => void poll(), delay);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [initial.invoices, initial.validTickets, orderId, router, token]);

  return (
    <Alert role="status">
      {!timedOut && <Loader2 className="size-4 animate-spin" />}
      <AlertTitle>{timedOut ? t('timeoutTitle') : t('title')}</AlertTitle>
      <AlertDescription>{timedOut ? t('timeoutText') : t('text')}</AlertDescription>
    </Alert>
  );
}
